const TZ = 'Europe/Rome';
const webhook = $('Webhook').first().json || {};
const q = webhook.query || {};

function clean(v){
  const s = String(v ?? '').trim();
  return ['undefined','null','[object object]'].includes(s.toLowerCase()) ? '' : s;
}
function partsInTz(date, timeZone){
  const out = {};
  new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year:'numeric', month:'2-digit', day:'2-digit',
    hour:'2-digit', minute:'2-digit', second:'2-digit', hour12:false
  }).formatToParts(date).forEach(p => { if (p.type !== 'literal') out[p.type] = p.value; });
  return out;
}
function todayInTz(){
  const p = partsInTz(new Date(), TZ);
  return `${p.year}-${p.month}-${p.day}`;
}
function validDate(s){
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return false;
  const [y,m,d] = s.split('-').map(Number);
  const x = new Date(Date.UTC(y,m-1,d));
  return x.getUTCFullYear() === y && x.getUTCMonth() === m-1 && x.getUTCDate() === d;
}
function addDays(s, n){
  const [y,m,d] = s.split('-').map(Number);
  const x = new Date(Date.UTC(y,m-1,d+n));
  return `${x.getUTCFullYear()}-${String(x.getUTCMonth()+1).padStart(2,'0')}-${String(x.getUTCDate()).padStart(2,'0')}`;
}
function dayDiff(a,b){
  const [ay,am,ad]=a.split('-').map(Number), [by,bm,bd]=b.split('-').map(Number);
  return Math.round((Date.UTC(by,bm-1,bd)-Date.UTC(ay,am-1,ad))/86400000);
}
function minDate(a,b){ return a <= b ? a : b; }
function maxDate(a,b){ return a >= b ? a : b; }

const rawDate = clean(q.date);
const requestedDateValid = !rawDate || validDate(rawDate);
const selected = rawDate && validDate(rawDate) ? rawDate : todayInTz();

const rawFrom = clean(q.range_from);
const rawTo = clean(q.range_to);
const rawDays = clean(q.trend_days);
let trendDays = Number.parseInt(rawDays || '7', 10);
if (!Number.isFinite(trendDays) || trendDays < 1 || trendDays > 90) trendDays = 7;

let rangeMode = 'quick';
let rangeStart = addDays(selected, -(trendDays-1));
let rangeEnd = selected;
let rangeValid = true;
let rangeLimited = false;

if (rawFrom || rawTo) {
  if (validDate(rawFrom) && validDate(rawTo) && rawFrom <= rawTo) {
    rangeMode = 'custom';
    rangeStart = rawFrom;
    rangeEnd = rawTo;
    const span = dayDiff(rangeStart, rangeEnd) + 1;
    if (span > 90) {
      rangeStart = addDays(rangeEnd, -89);
      rangeLimited = true;
    }
  } else {
    rangeValid = false;
  }
}

const rangeDaysCount = dayDiff(rangeStart, rangeEnd) + 1;
// Una sola query Directus copre sia il giorno principale sia il range trend.
const queryStartDay = minDate(selected, rangeStart);
const queryEndDay = maxDate(selected, rangeEnd);
const queryFrom = `${queryStartDay}T00:00:00`;
const queryTo = `${addDays(queryEndDay, 1)}T00:00:00`;

return [{ json: {
  timezone: TZ,
  selected_date: selected,
  requested_date: rawDate || null,
  requested_date_valid: requestedDateValid,
  range_mode: rangeMode,
  range_start: rangeStart,
  range_end: rangeEnd,
  range_days_count: rangeDaysCount,
  requested_range_valid: rangeValid,
  range_limited: rangeLimited,
  trend_days_requested: trendDays,
  query_from: queryFrom,
  query_to: queryTo
} }];

