  non_handoff: rangeNonHandoff,
  drops: Object.fromEntries(rangeDropoff.map(x => [x.key, {count:x.count,pct:x.pct,share_non_handoff:x.share_non_handoff}]))
};

let qualityStatus = 'ok';
if (!logsAvailable) qualityStatus = 'error';
else if (warnings.some(w=>w.severity==='error' || w.severity==='warning')) qualityStatus = 'partial';

const response = {
  date: meta.selected_date,
  timezone: TZ,
  generated_at: new Date().toISOString(),
  date_basis: 'call_log_details.date_created',
  date_basis_label: 'giorno di registrazione in Directus',
  macro: {
    calls: logsAvailable ? selected.total : null,
    avg_duration_sec: logsAvailable ? selected.avg_duration_sec : null,
    reached_valentina: logsAvailable ? selected.counts[2] : null,
