  },
  transfers: {
    requested: { value: (logsAvailable && callsAvailable) ? selected.handoff_requested : null, status:(logsAvailable && callsAvailable)?'certified':'not_certified' },
    completed: { value: selected.transfer_outcomes.status==='not_certified' ? null : selected.transfer_outcomes.completed, status:selected.transfer_outcomes.status },
    lead_no_operator: { value: selected.transfer_outcomes.status==='not_certified' ? null : selected.transfer_outcomes.lead_no_operator, status:selected.transfer_outcomes.status },
    errors: {
      value: selected.transfer_outcomes.status==='not_certified' ? null : selected.transfer_outcomes.other_failures,
      status:selected.transfer_outcomes.status,
      breakdown: selected.transfer_outcomes.status==='not_certified' ? null : {
        failure_non_occupati:selected.transfer_outcomes.other_failures,
