      }
    },
    outcome_coverage: {
      classified: selected.transfer_outcomes.status==='not_certified' ? null : selected.transfer_outcomes.classified,
      unclassified: selected.transfer_outcomes.status==='not_certified' ? null : selected.transfer_outcomes.unclassified,
      coverage_pct: selected.transfer_outcomes.status==='not_certified' ? null : selected.transfer_outcomes.coverage_pct,
      status:selected.transfer_outcomes.status
    }
  },
  funnel: logsAvailable ? selected.funnel : funnelDefs.map(d=>({...d,count:null,pct_total:null,pct_previous:null,drop_count:null,drop_pct:null})),
  dropoff: logsAvailable ? dropoff : [],
  non_handoff: (logsAvailable && callsAvailable) ? { count:selectedNonHandoff, share_basis:'chiamate senza richiesta operatore' } : { count:null, share_basis:'chiamate senza richiesta operatore' },
  errors: {
    call_errors: logsAvailable ? selected.call_errors : {count:null,pct:null,by_code:null},
